#pragma once

inline constexpr char HEADLESS_PORTAL_PAGE[] = R"HTML(<!doctype html><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>伊迪斯设备</title>
<style>body{font:16px sans-serif;max-width:40em;margin:2em auto;padding:0 1em}input,button{font:inherit;margin:.4em;padding:.5em}pre{white-space:pre-wrap}#code{font-size:2em;letter-spacing:.3em}</style>
<h1>伊迪斯设备</h1><p>此页面只在连接设备热点时可用，查看窗口最长10分钟。<span id=gesture>绑定后使用本机查看按键重新开启。</span></p>
<section id=setup hidden><h2>配置网络</h2><p>保存后设备会重启。请重新连接“助手-配置”热点，刷新本页读取六位绑定码，再到控制台添加设备。</p><form id=f><label>Wi-Fi <input name=ssid required></label><br><label>密码 <input name=password type=password></label><br><label>服务地址 <input name=server required placeholder=ws://bridge/device/v1/></label><details><summary>已有设备凭据</summary><input name=token type=password minlength=24></details><button>保存并连接</button></form></section>
<h2 id=status>读取状态…</h2><p id=message></p><div id=code></div><p id=expiry></p>
<article id=card hidden><h2 id=title></h2><pre id=detail></pre><p id=clock></p><p id=delivery>内容呈现后确认送达；送达不代表待办完成。</p><div id=actions></div></article>
<script>
let session='',current=null,seenKey='',busy=false;
const elements=Object.fromEntries(['setup','status','message','code','expiry','card','title','detail','clock','delivery','actions','f','gesture'].map(id=>[id,document.getElementById(id)]));
const stateNames=['待命','正在聆听','正在回答','正在思考','正在处理','正在连接','请留意','发生错误','提醒','固件更新中'];
async function fetchText(path,options={}){const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),5000);try{const response=await fetch(path,{...options,cache:'no-store',signal:controller.signal});return {ok:response.ok,text:await response.text()}}finally{clearTimeout(timeout)}}
async function request(path,body){let r=await fetchText(path,{method:body?'POST':'GET',headers:{'X-Device-Session':session,...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{})});if(!r.ok)throw new Error('设备暂未接受请求，请刷新状态');return JSON.parse(r.text)}
function binding(action,c){return {card_id:c.card_id,revision:c.reference_revision,generation:c.generation,action}}
function addAction(label,action,disabled){const target=current;let b=document.createElement('button');b.textContent=label;b.disabled=disabled;b.onclick=async()=>{b.disabled=true;try{await request('/device/action',binding(action,target));elements.message.textContent=action==='close'?'已关闭本机提示':'请求已提交，等待设备状态确认'}catch(e){elements.message.textContent=e.message}seenKey=''};elements.actions.append(b)}
async function refresh(){if(busy)return;busy=true;try{if(!session){let r=await fetchText('/device/session');if(!r.ok)throw Error('请连接设备热点后刷新');let s=JSON.parse(r.text);session=s.session;elements.setup.hidden=!s.configure;elements.gesture.textContent=s.portal_gesture}
let s=await request('/device/status');elements.status.textContent=stateNames[s.state]||'设备状态';elements.message.textContent=s.detail||'';elements.code.textContent=s.pairing_code||'';elements.expiry.textContent=s.pairing_code?'绑定码剩余约'+s.pairing_seconds+'秒；请在控制台输入':'';current=s.card;elements.card.hidden=!current;elements.actions.replaceChildren();if(current){elements.title.textContent=current.title;elements.detail.textContent=current.detail;elements.clock.textContent=current.kind==='timer'?'剩余约'+current.remaining_s+'秒 / '+current.status:'';let key=current.card_id+'|'+current.reference_revision+'|'+current.generation;if(key!==seenKey&&document.visibilityState==='visible'){await new Promise(resolve=>{const deadline=setTimeout(resolve,200);requestAnimationFrame(()=>requestAnimationFrame(()=>{clearTimeout(deadline);resolve()}))});if(document.visibilityState==='visible'){await request('/device/action',binding('seen',current));seenKey=key}}const disabled=s.action_pending||(!s.linked);if(current.kind==='reminder'){addAction('稍后5分钟','snooze',disabled||!current.reference_revision);addAction('知道了','close',s.action_pending)}else{if(current.status==='running')addAction('暂停','pause',disabled);if(current.status==='paused')addAction('继续','resume',disabled);addAction('取消','cancel',disabled)}}}
catch(e){elements.message.textContent='连接可能已关闭或请求未被接受。请确认仍连接设备热点；绑定结果到控制台核查。';session=''}finally{busy=false}}
elements.f.onsubmit=async e=>{e.preventDefault();try{let r=await fetchText('/configure',{method:'POST',headers:{'Content-Type':'application/json','X-Device-Session':session},body:JSON.stringify(Object.fromEntries(new FormData(elements.f)))});elements.message.textContent=r.text}catch(e){elements.message.textContent='连接已断开；请重新连接设备热点，核查配置和绑定状态'}};
refresh();setInterval(refresh,2000);
</script>)HTML";
